
        CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, created_at BIGINT NOT NULL);
        CREATE TABLE IF NOT EXISTS businesses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES users(id), name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, industry TEXT NOT NULL, accent TEXT NOT NULL DEFAULT '#dba76b', tagline TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
        CREATE TABLE IF NOT EXISTS memberships(business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('owner','manager','staff')),PRIMARY KEY (business_id,user_id));
        CREATE TABLE IF NOT EXISTS stations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, label TEXT NOT NULL, code TEXT NOT NULL, token TEXT UNIQUE NOT NULL, active BIGINT NOT NULL DEFAULT 1, created_at BIGINT NOT NULL, UNIQUE(business_id,code));
        CREATE TABLE IF NOT EXISTS products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'Featured', price_cents BIGINT NOT NULL DEFAULT 0, active BIGINT NOT NULL DEFAULT 1);
        CREATE TABLE IF NOT EXISTS requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, station_id BIGINT NOT NULL REFERENCES stations(id), kind TEXT NOT NULL, message TEXT NOT NULL DEFAULT '', product_id BIGINT REFERENCES products(id), status TEXT NOT NULL DEFAULT 'open', receipt_hash TEXT NOT NULL, client_key TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE(business_id,client_key));
        CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at BIGINT NOT NULL);
        CREATE TABLE IF NOT EXISTS invites(token_hash TEXT PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,role TEXT NOT NULL,expires_at BIGINT NOT NULL,used_at BIGINT);
        CREATE TABLE IF NOT EXISTS scans(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,station_id BIGINT NOT NULL REFERENCES stations(id),business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,created_at BIGINT NOT NULL);
        CREATE INDEX IF NOT EXISTS idx_requests ON requests(business_id,status,created_at DESC);
        CREATE INDEX IF NOT EXISTS idx_sessions ON sessions(expires_at);
        CREATE INDEX IF NOT EXISTS idx_scans ON scans(business_id,created_at DESC);
        
ALTER TABLE stations ADD CONSTRAINT stations_tenant_id UNIQUE(business_id,id);
ALTER TABLE products ADD CONSTRAINT products_tenant_id UNIQUE(business_id,id);
ALTER TABLE requests ADD CONSTRAINT request_station_tenant FOREIGN KEY(business_id,station_id) REFERENCES stations(business_id,id);
ALTER TABLE requests ADD CONSTRAINT request_product_tenant FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id);
ALTER TABLE scans ADD CONSTRAINT scan_station_tenant FOREIGN KEY(business_id,station_id) REFERENCES stations(business_id,id);
ALTER TABLE requests ADD CONSTRAINT request_status CHECK(status IN ('open','in_progress','completed'));
ALTER TABLE invites ADD CONSTRAINT invite_role CHECK(role IN ('staff','manager'));
